import{_ as p,a0 as r,w as l,s,ao as d,I as a,x as e,a1 as i,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"如何在 Linux 上用 IP轉發使內部網絡連接到互聯網 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上用 IP轉發使內部網絡連接到互聯網 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上用 IP轉發使內部網絡連接到互聯網 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上用 IP轉發使內部網絡連接到互聯網 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150423 How IP forwarding Helps Connecting Private interface to Internet in Linux","title":"如何在 Linux 上用 IP轉發使內部網絡連接到互聯網","tag":"201506","desc":""},"relativePath":"201506/20150423 How IP forwarding Helps Connecting Private interface to Internet in Linux.md","filePath":"[post].md"}'),c={name:"201506/20150423 How IP forwarding Helps Connecting Private interface to Internet in Linux.md"};function f(g,t,u,x,m,h){const n=r("Link");return l(),s("div",null,[t[13]||(t[13]=d(`<h1 id="如何在-linux-上用-ip轉發使內部網絡連接到互聯網" tabindex="-1">如何在 Linux 上用 IP轉發使內部網絡連接到互聯網 <a class="header-anchor" href="#如何在-linux-上用-ip轉發使內部網絡連接到互聯網" aria-label="Permalink to “如何在 Linux 上用 IP轉發使內部網絡連接到互聯網”">​</a></h1><p>大家好，今天我們學習一下在 Linux 上用 iptables 實現從一個網絡接口到另一個接口的IP轉發（數據包轉發）。IP轉發的概念是，使 Linux 機器像路由器一樣將數據從一個網絡發送到另一個網絡。所以，它能作為一個<strong>路由器</strong>或者代理服務器，實現將一個連接的互聯網或者網絡連接共享給多個客户端機器。</p><p>這是一些啓用IP轉發或網絡包轉發方法的簡單步驟。</p><h3 id="_1-啓用-ipv4-轉發" tabindex="-1">1. 啓用 IPv4 轉發 <a class="header-anchor" href="#_1-啓用-ipv4-轉發" aria-label="Permalink to “1. 啓用 IPv4 轉發”">​</a></h3><p>首先，我們需要在我們的 Linux 操作系統上啓用 IPv4 轉發。要做到這點，我們需要用 sudo 模式在 shell 或終端下執行下面的命令。</p><pre><code>$ sudo -s

# echo 1 &gt; /proc/sys/net/ipv4/ip_forward
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ip-forward-temporary.png" alt="臨時IP轉發"></p><p><strong>注意：上面的命令能馬上啓用ip轉發，但只是臨時的，直到下一次重啓。要永久啓用，我們需要使用我們慣用的文本編輯器打開 /etc/sysctl.conf 文件。</strong></p><pre><code># nano /etc/sysctl.conf
</code></pre><p>然後，增加 <strong>net.ipv4.ip_forward = 1</strong> 到文件中，或者刪除那行的註釋，保存並退出文件。</p><pre><code>net.ipv4.ip_forward = 1
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/sysctl-edit.png" alt="編輯 Sysctl"></p><p>運行下面的命令啓用更改。</p><pre><code># sysctl -p /etc/sysctl.conf
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/enabling-changes-sysctl.png" alt="啓用 Sysctl 更改"></p><h3 id="_2-配置-iptables-防火牆" tabindex="-1">2. 配置 Iptables 防火牆 <a class="header-anchor" href="#_2-配置-iptables-防火牆" aria-label="Permalink to “2. 配置 Iptables 防火牆”">​</a></h3><p>我們需要允許特定的(或者所有的)數據包通過我們的路由器。在這之前，我們要知道連接我們 Linux 的網絡設備的接口名稱。我們可以通過在終端或者 shell 運行以下命令獲得接口名稱。</p><pre><code># ifconfig -a
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/ifconfig.png" alt="Ifconfig"></p><p>這裏，在我們的機器中， eth2 是連接到互聯網或者網絡的網卡接口， wlan2 是我們要使用 iptables 從 eth2 轉發數據包的接口。要實現轉發，我們需要運行以下命令。</p><pre><code># iptables -A FORWARD -i wlan2 -o eth2 -j ACCEPT
</code></pre><p>注意：請用你 Linux 機器中的可用設備名稱替換 wlan2 和 eth2。</p><p>現在，由於netfilter/iptables是一個無狀態的防火牆，我們需要讓 iptables 允許已建立的連接通過。要做到這點，我們要運行下面的命令。</p><pre><code># iptables -A FORWARD -i eth2 -o wlan2 -m state --state ESTABLISHED,RELATED  -j ACCEPT
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/forwarding-iptables.png" alt="用 iptables 轉發"></p><h3 id="_3-配置-nat" tabindex="-1">3. 配置 NAT <a class="header-anchor" href="#_3-配置-nat" aria-label="Permalink to “3. 配置 NAT”">​</a></h3><p>然後，最後我們需要通過執行下面的命令修改發送到互聯網的數據包的源地址為 eth2。</p><pre><code># iptables -t nat -A POSTROUTING -o eth2 -j MASQUERADE
</code></pre><p><img src="http://blog.linoxide.com/wp-content/uploads/2015/03/configuring-nat.png" alt="配置 nat"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>最後，我們在我們以 iptables 作為防火牆 Linux 機器上成功的配置了從一個接口到另一個接口的數據包轉發。這篇文章教給你將你的私有接口連接到互聯網，不需要橋接接口，而是將從一個接口進來的數據包路由到另一個接口。就是這些，如果你有任何問題、建議、反饋，請寫到下面的評論框中，然後我們可以改進或更新我們的內容。非常感謝！享受吧 😃</p><hr>`,32)),a("p",null,[t[1]||(t[1]=e("via: ",-1)),i(n,{href:"http://linoxide.com/firewall/ip-forwarding-connecting-private-interface-internet/"},{default:o(()=>[...t[0]||(t[0]=[e("http://linoxide.com/firewall/ip-forwarding-connecting-private-interface-internet/",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=e("作者：",-1)),i(n,{href:"http://linoxide.com/author/arunp/"},{default:o(()=>[...t[2]||(t[2]=[e("Arun Pyasi",-1)])]),_:1}),t[6]||(t[6]=e(" 譯者：",-1)),i(n,{href:"https://github.com/ictlyh"},{default:o(()=>[...t[3]||(t[3]=[e("ictlyh",-1)])]),_:1}),t[7]||(t[7]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:o(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原創翻譯，",-1)),i(n,{href:"http://linux.cn/"},{default:o(()=>[...t[9]||(t[9]=[e("Linux中國",-1)])]),_:1}),t[12]||(t[12]=e(" 榮譽推出",-1))])])}const T=p(c,[["render",f]]);export{w as __pageData,T as default};
